newString: """Edge-cache key normalization."""
from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode


def cache_key(url):
    """Normalize a URL into an edge-cache key."""
    if not url:
        return ""

    parsed = urlparse(url.strip())

    scheme = parsed.scheme.lower()
    netloc = parsed.netloc.lower()
    path = parsed.path

    query_params = parse_qsl(parsed.query, keep_blank_values=True)
    filtered_params = []
    for name, value in query_params:
        if not value:
            continue
        name_lower = name.lower()
        if name_lower in ('gclid', 'fbclid', 'msclkid'):
            continue
        if name_lower.startswith('utm_') and name_lower != 'utm_content':
            continue
        filtered_params.append((name, value))

    filtered_params.sort(key=lambda x: x[0])

    if filtered_params:
        query_string = urlencode(filtered_params)
    else:
        query_string = ''

    return urlunparse((scheme, netloc, path, parsed.params, query_string, parsed.fragment))

