content: """CSV writer for the ERP import."""


def to_csv(rows, columns):
    """Render rows (list of dicts) as CSV text for the ERP import."""
    def format_field(val):
        if val is None:
            return ""
        s = str(val)
        if len(s) > 1 and s.startswith('0') and s.isdigit():
            return f'="{s}"'
        if ',' in s or '"' in s or '\n' in s or '\r' in s:
            return f'"{s.replace(\'"\', \'""\')}"'
        return s

    lines = [",".join(columns)]
    for row in rows:
        lines.append(",".join(format_field(row.get(col)) for col in columns))
    return "\r\n".join(lines) + "\r\n"

