newString: def merge_records(primary, incoming):
    """Merge incoming sync records into the primary list, dropping duplicate contacts."""
    out = []
    slot = {}
    slot_is_crm = {}

    def count_non_empty(r):
        return sum(1 for k, v in r.items() if v is not None and v != "")

    def should_replace(existing, existing_is_crm, candidate, candidate_is_crm):
        existing_count = count_non_empty(existing)
        candidate_count = count_non_empty(candidate)

        if candidate_count > existing_count:
            return True
        if candidate_count < existing_count:
            return False

        if candidate_is_crm and not existing_is_crm:
            return True
        if existing_is_crm and not candidate_is_crm:
            return False

        existing_updated = existing.get("updated", "")
        candidate_updated = candidate.get("updated", "")
        return candidate_updated > existing_updated

    for rec, is_crm in [(r, True) for r in primary] + [(r, False) for r in incoming]:
        email = str(rec.get("email", "")).lower()
        updated_str = str(rec.get("updated", ""))
        day = updated_str[:10] if len(updated_str) >= 10 else updated_str

        key = (email, day)
        if key in slot:
            i = slot[key]
            existing = out[i]
            existing_is_crm = slot_is_crm[i]
            if should_replace(existing, existing_is_crm, rec, is_crm):
                out[i] = rec
                slot_is_crm[i] = is_crm
        else:
            i = len(out)
            slot[key] = i
            slot_is_crm[i] = is_crm
            out.append(rec)

    return out
