newString: def is_allowed(host, allowlist):
    """Check an outbound host against the egress allowlist."""
    host_norm = host.lower().rstrip('.')

    # Check if host is an IP address
    host_is_ip = False
    try:
        import ipaddress
        ipaddress.ip_address(host_norm)
        host_is_ip = True
    except ValueError:
        pass

    for entry in allowlist:
        entry_norm = entry.lower().rstrip('.')
        if entry_norm.startswith("*."):
            if host_is_ip:
                continue
            suffix = entry_norm[2:]
            if host_norm.endswith("." + suffix):
                prefix = host_norm[:-len("." + suffix)]
                if prefix and '.' not in prefix:
                    return True
        elif host_norm == entry_norm:
            return True
    return False
