newString: """Egress allowlist matching."""
import ipaddress


def _is_ip_address(s):
    try:
        ipaddress.ip_address(s)
        return True
    except ValueError:
        return False


def _normalize_host(h):
    h = h.lower()
    if not _is_ip_address(h):
        if not h.endswith('.'):
            h = h + '.'
    return h


def is_allowed(host, allowlist):
    """Check an outbound host against the egress allowlist."""
    host_is_ip = _is_ip_address(host)
    norm_host = _normalize_host(host)
    for entry in allowlist:
        entry_is_ip = _is_ip_address(entry)
        norm_entry = _normalize_host(entry)

        if host_is_ip or entry_is_ip:
            # Exact-only matching for IP literals
            if norm_host == norm_entry:
                return True
        else:
            # Domain names matching
            if '*' in norm_entry:
                host_parts = norm_host.rstrip('.').split('.')
                entry_parts = norm_entry.rstrip('.').split('.')
                if len(host_parts) == len(entry_parts):
                    match = True
                    for h_p, e_p in zip(host_parts, entry_parts):
                        if e_p != '*' and h_p != e_p:
                            match = False
                            break
                    if match:
                        return True
            else:
                if norm_host == norm_entry:
                    return True
    return False

