newString: """Redact sensitive fields from log events."""
import re

_SENSITIVE_SUFFIXES = ("password", "token", "api_key", "ssn", "card_number")


def _normalize_key(key):
    if not isinstance(key, str):
        return str(key)
    return re.sub(r"[^a-zA-Z0-9]", "_", key.lower())


def redact(event):
    """Mask sensitive fields in a log event."""
    if isinstance(event, dict):
        out = {}
        for k, v in event.items():
            k_norm = _normalize_key(k)
            is_sensitive = False
            for suffix in _SENSITIVE_SUFFIXES:
                if k_norm.endswith(suffix):
                    is_sensitive = True
                    break
            if is_sensitive:
                if k_norm.endswith("card_number"):
                    out[k] = f"***{str(v)[-4:]}"
                else:
                    out[k] = "***"
            else:
                out[k] = redact(v)
        return out
    elif isinstance(event, list):
        return [redact(item) for item in event]
    elif isinstance(event, tuple):
        return tuple(redact(item) for item in event)
    else:
        return event
