newString: def append_event(ledger, event):
    """Record an audit event in the tenant's sequence."""
    tenant = event["tenant"]
    events = ledger.setdefault(tenant, [])
    seq = event["seq"]

    for stored in events:
        if stored["seq"] == seq:
            if stored.get("payload_hash") == event.get("payload_hash"):
                return True
            else:
                raise SequenceConflictError("Conflict at seq %d for tenant %s: payload hash mismatch" % (seq, tenant))

    if not events:
        if seq != 1:
            raise SequenceGapError("First event for tenant %s must be seq 1, got %d" % (tenant, seq))
    else:
        last_seq = events[-1]["seq"]
        is_compaction = (event.get("type") == "compaction")
        if is_compaction:
            if seq != last_seq + 100:
                raise SequenceGapError("Compaction event for tenant %s must increment seq by 100 (expected %d, got %d)" % (tenant, last_seq + 100, seq))
