newString: def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    # 1. Filter maintenance periods that were announced at least 24 hours in advance
    valid_maint = []
    for m in maintenance:
        if "announced_at" in m:
            start = _t(m["start"])
            announced = _t(m["announced_at"])
            if (start - announced) >= timedelta(hours=24):
                valid_maint.append((start, _t(m["end"])))

    # 2. Merge overlapping or touching incident windows
    sorted_incidents = []
    for inc in incidents:
        sorted_incidents.append((_t(inc["start"]), _t(inc["end"])))
    sorted_incidents.sort(key=lambda x: x[0])

    merged_incidents = []
    for start, end in sorted_incidents:
        if not merged_incidents:
            merged_incidents.append((start, end))
        else:
            prev_start, prev_end = merged_incidents[-1]
            if start <= prev_end:
                merged_incidents[-1] = (prev_start, max(prev_end, end))
            else:
                merged_incidents.append((start, end))

    # 3. Filter out merged outages shorter than 60 seconds (monitoring blips)
    active_incidents = []
    for start, end in merged_incidents:
        if (end - start).total_seconds() >= 60.0:
            active_incidents.append((start, end))

    # 4. Merge valid maintenance windows to avoid double subtraction
    sorted_maint = sorted(valid_maint, key=lambda x: x[0])
    merged_maint = []
    for start, end in sorted_maint:
        if not merged_maint:
            merged_maint.append((start, end))
        else:
            prev_start, prev_end = merged_maint[-1]
            if start <= prev_end:
                merged_maint[-1] = (prev_start, max(prev_end, end))
            else:
                merged_maint.append((start, end))

    # 5. Calculate total downtime subtracting valid maintenance overlap
    total_seconds = 0.0
    for inc_start, inc_end in active_incidents:
        span = (inc_end - inc_start).total_seconds()
        for m_start, m_end in merged_maint:
            lo = max(inc_start, m_start)
            hi = min(inc_end, m_end)
            span -= max((hi - lo).total_seconds(), 0.0)
        total_seconds += span

    return total_seconds / 60.0
oldString: def downtime_minutes(incidents, maintenance):
    """Total SLA downtime in minutes for a billing period."""
    total = 0.0
    for inc in incidents:
        start, end = _t(inc["start"]), _t(inc["end"])
        span = (end - start).total_seconds()
        for m in maintenance:
            lo = max(start, _t(m["start"]))
            hi = min(end, _t(m["end"]))
            span -= max((hi - lo).total_seconds(), 0.0)
        total += span
    return total / 60.0

