newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    tombstones_by_source = []
    for tags in sources:
        tombstones = set()
        for tag in tags:
            if tag.startswith('-') and len(tag) > 1:
                tombstones.add(tag[1:].lower())
        tombstones_by_source.append(tombstones)

    out = []
    seen = set()
    for j, tags in enumerate(sources):
        for tag in tags:
            if tag.startswith('-'):
                continue

            tag_lower = tag.lower()
            suppressed = False
            for i in range(j):
                if tag_lower in tombstones_by_source[i]:
                    suppressed = True
                    break

            if suppressed:
                continue

            if tag_lower not in seen:
                seen.add(tag_lower)
                out.append(tag)

    return out

