newString: def merge_tags(sources):
    """Merge tag lists from every source into one combined list."""
    blocked_at_source = [set() for _ in range(len(sources))]
    active_tombstones = set()

    for i in range(len(sources)):
        blocked_at_source[i] = set(active_tombstones)
        for tag in sources[i]:
            if tag.startswith('-') and len(tag) > 1:
                active_tombstones.add(tag[1:].lower())

    out = []
    seen_lower = set()

    for i in range(len(sources)):
        for tag in sources[i]:
            if tag.startswith('-') and len(tag) > 1:
                continue
            tag_lower = tag.lower()
            if tag_lower in blocked_at_source[i]:
                continue
            if tag_lower not in seen_lower:
                out.append(tag)
                seen_lower.add(tag_lower)

    return out
