filePath: /work/infraconf/units.py
content: """Config quantity parsing for the provisioning pipeline."""


def parse_quantity(value, kind):
    """Convert a config quantity like '512M' into bytes for the given
    resource kind ("memory" or "disk")."""
    s = str(value).strip()
    if not s:
        raise ValueError("empty quantity")

    if s[-1].isalpha():
        suffix = s[-1].upper()
        if kind == "memory":
            units = {"K": 1024, "M": 1024 ** 2, "G": 1024 ** 3, "T": 1024 ** 4}
        elif kind == "disk":
            units = {"M": 1000 ** 2, "G": 1000 ** 3, "T": 1000 ** 4}
        else:
            raise ValueError("unknown resource kind: " + str(kind))

        if suffix not in units:
            raise ValueError("invalid unit suffix for " + kind + ": " + s[-1])
        return int(s[:-1]) * units[suffix]

    if kind == "memory":
        multiplier = 1024 ** 2
    elif kind == "disk":
        multiplier = 1000 ** 3
    else:
        raise ValueError("unknown resource kind: " + str(kind))

    return int(s) * multiplier

