content: """Config quantity parsing for the provisioning pipeline."""

_UNITS = {"K": 1000, "M": 1000 ** 2, "G": 1000 ** 3, "T": 1000 ** 4}


def parse_quantity(value, kind):
    """Convert a config quantity like '512M' into bytes for the given
    resource kind ("memory" or "disk")."""
    s = str(value).strip()
    if not s:
        raise ValueError("empty value")

    if s[-1].isalpha():
        suffix = s[-1].upper()
        # Parse the numeric part before the suffix
        try:
            num = int(s[:-1])
        except ValueError:
            raise ValueError("invalid number format: " + s)

        if kind == "memory":
            memory_units = {
                "K": 1024,
                "M": 1024 ** 2,
                "G": 1024 ** 3,
                "T": 1024 ** 4
            }
            if suffix not in memory_units:
                raise ValueError("invalid unit suffix for " + kind + ": " + s[-1])
            return num * memory_units[suffix]

        elif kind == "disk":
            disk_units = {
                "M": 1000 ** 2,
                "G": 1000 ** 3,
                "T": 1000 ** 4
            }
            if suffix == "K":
                raise ValueError("K suffix is not allowed for disk")
            if suffix not in disk_units:
                raise ValueError("invalid unit suffix for " + kind + ": " + s[-1])
            return num * disk_units[suffix]
        else:
            raise ValueError("unknown resource kind: " + kind)

    else:
        # Bare number
        try:
            num = int(s)
        except ValueError:
            raise ValueError("invalid number format: " + s)

        if kind == "memory":
            return num * (1024 ** 2)  # defaults to MiB
        elif kind == "disk":
            return num * (1000 ** 3)  # defaults to GB
        else:
            raise ValueError("unknown resource kind: " + kind)

